function dt(s){return String(s).replace(/(\d+) (janv\.|févr\.|mars|avril|mai|juin|juil\.|août|sept\.|oct\.|nov\.|déc\.) (\d{4})/,function(a,d,mo,y){return MO[mo]+' '+d+', '+y})}
function T(s){var k=n(s);if(!k||!/[A-Za-zÀ-ÿ]/.test(k))return null;if(Object.prototype.hasOwnProperty.call(D,k))return D[k];
 for(var i=0;i<P.length;i++){var m=k.match(P[i][0]);if(m)return typeof P[i][1]==='function'?P[i][1](m):k.replace(P[i][0],P[i][1])}
 if(k.indexOf(' · ')>0){var ch=0,o=k.split(' · ').map(function(x){var t=Object.prototype.hasOwnProperty.call(D,x)?D[x]:null;if(t!=null){ch=1;return t}return x});if(ch)return o.join(' · ')}
 return null}
window.mxT=function(s){var t=T(s);return t==null?s:t};
var SKIP=/^(SCRIPT|STYLE|TEXTAREA|CODE|NOSCRIPT)$/;
var done=new WeakMap();
function tn(nd){var v=nd.nodeValue;if(!v||done.get(nd)===v)return;var p=nd.parentNode;if(p&&(SKIP.test(p.nodeName)||(p.closest&&p.closest('[data-noi18n],.chat-msg-text,.comment-text,.fm-bubble'))))return;
 var m=v.match(/^(\s*)([\s\S]*?)(\s*)$/),t=T(m[2]);if(t!=null&&t!==m[2]){v=m[1]+t+m[3];nd.nodeValue=v}done.set(nd,v)}
var AT=['placeholder','title','aria-label','alt'];
function el(e){if(/^(SCRIPT|STYLE)$/.test(e.nodeName))return;for(var i=0;i<AT.length;i++){var a=e.getAttribute(AT[i]);if(a){var t=T(a);if(t!=null&&t!==a)e.setAttribute(AT[i],t)}}
 if(e.nodeName==='INPUT'&&e.value&&(/^(button|submit)$/.test(e.type)||/^Joueur \d+$/.test(e.value))){var t2=T(e.value);if(t2!=null)e.value=t2}}
function walk(r){if(r.nodeType===3)return tn(r);if(r.nodeType!==1)return;el(r);if(SKIP.test(r.nodeName))return;var w=document.createTreeWalker(r,5,null),x;while(x=w.nextNode()){if(x.nodeType===3)tn(x);else el(x)}}
window.mxI18nWalk=walk;
var mo=new MutationObserver(function(ms){for(var i=0;i<ms.length;i++){var m=ms[i];if(m.type==='characterData')tn(m.target);else if(m.type==='attributes')el(m.target);else for(var j=0;j<m.addedNodes.length;j++)walk(m.addedNodes[j])}});
mo.observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:AT});
document.addEventListener('DOMContentLoaded',function(){walk(document.documentElement)});
// alert/confirm/prompt
['alert','confirm','prompt'].forEach(function(f){var o=window[f];if(!o)return;window[f]=function(a,b){return o.call(window,a==null?a:window.mxT(String(a)),b)}});
// données du catalogue
function tSeason(s){if(!s)return s;if(SE[s])return SE[s];return s}
window.mxApplyEN=function(){
 var lists=[];try{lists.push(['a',ANIME])}catch(e){}try{lists.push(['m',MANGA])}catch(e){}
 var TI={'a:aot':'Attack on Titan','m:aot-manga':'Attack on Titan'};
 lists.forEach(function(L){L[1].forEach(function(it){var k=L[0]+':'+it.id;if(S[k])it.summary=S[k];if(TI[k])it.title=TI[k];if(it.author)it.author=it.author.replace(/\(scénario\)/g,'(story)').replace(/\(dessin\)/g,'(art)').replace(/\(roman\)/g,'(novel)');if(it.seasons)it.seasons=tSeason(it.seasons);if(it.status&&ST[it.status])it.status=ST[it.status];
  (it.characters||[]).forEach(function(c,i){if(R[c.role])c.role=R[c.role];var cd=CD[k+'#'+c.name];if(cd)c.desc=cd});(it.ost||[]).forEach(function(o){if(TG[o.tag])o.tag=TG[o.tag]})})});
 try{Object.keys(EXTRA_CHARS).forEach(function(key){EXTRA_CHARS[key].forEach(function(c){if(R[c.role])c.role=R[c.role];var cd=CD[(key[0]==='a'?'a':'m')+':'+key.split(':')[1]+'#'+c.name];if(cd)c.desc=cd})})}catch(e){}
};
